import importlib.util as u, importlib.metadata as m, json, sys
out={"python":sys.executable,"modules":{},"entry_points":{}}
for module,distribution in [("openai","openai"),("uvloop","uvloop"),("vllm","vllm"),("vllm_tt_plugin","vllm-tt-plugin")]:
 s=u.find_spec(module)
 try: version=m.version(distribution)
 except m.PackageNotFoundError: version=None
 out["modules"][module]={"found":s is not None,"origin":None if s is None else s.origin,"distribution_version":version}
for group in ["vllm.general_plugins","vllm.platform_plugins"]:
 out["entry_points"][group]=[(p.name,p.value) for p in m.entry_points(group=group)]
print(json.dumps(out,indent=2))

